// The ONE place the frontend learns about the deployed contract.
// contract.json is generated by `npm run deploy` (scripts/deploy.ts) at the repo root.
import deployment from "./contract.json";
import type { InterfaceAbi } from "ethers";

export const CONTRACT_ADDRESS: string = deployment.address;
export const CONTRACT_ABI = deployment.abi as unknown as InterfaceAbi;
export const CHAIN_ID: number = deployment.chainId;
export const DEPLOY_BLOCK: number = deployment.deployBlock;
export const POLICY = deployment.policy;

export const RPC_URL: string = import.meta.env.VITE_RPC_URL || "http://127.0.0.1:8545";
/** Block explorer base URL (e.g. https://sepolia.etherscan.io). Empty for the local Hardhat node. */
export const EXPLORER_URL: string = (import.meta.env.VITE_EXPLORER_URL || "").replace(/\/$/, "");

export const NETWORK = {
  chainId: CHAIN_ID,
  chainIdHex: "0x" + CHAIN_ID.toString(16),
  name: "Hardhat Local",
  rpcUrl: RPC_URL,
  currency: { name: "Ether", symbol: "ETH", decimals: 18 },
};

export const POLL_INTERVAL_MS = 4000;
